433	func (v *ViewChanger) prepareViewDataMsg() *protos.Message {
434		lastDecision, lastDecisionSignatures := v.Checkpoint.Get()
435		inFlight := v.getInFlight(lastDecision)
436		prepared := v.InFlight.IsInFlightPrepared()
437		vd := &protos.ViewData{
438			NextView:               v.currView,
439			LastDecision:           lastDecision,
440			LastDecisionSignatures: lastDecisionSignatures,
441			InFlightProposal:       inFlight,
442			InFlightPrepared:       prepared,
443		}
444		vdBytes := MarshalOrPanic(vd)
445		sig := v.Signer.Sign(vdBytes)
446		msg := &protos.Message{
447			Content: &protos.Message_ViewData{
448				ViewData: &protos.SignedViewData{
449					RawViewData: vdBytes,
450					Signer:      v.SelfID,
451					Signature:   sig,
452				},
453			},
454		}
455		return msg
456	}
