680	// ValidateLastDecision validates the given decision, and returns its sequence when valid
681	func ValidateLastDecision(vd *protos.ViewData, quorum int, n uint64, verifier api.Verifier) (lastSequence uint64, err error) {
682		if vd.LastDecision == nil {
683			return 0, errors.New("the last decision is not set")
684		}
685		if vd.LastDecision.Metadata == nil {
686			// This is a genesis proposal, there are no signatures to validate, so we return at this point
687			return 0, nil
688		}
689		md := &protos.ViewMetadata{}
690		if err = proto.Unmarshal(vd.LastDecision.Metadata, md); err != nil {
691			return 0, fmt.Errorf("unable to unmarshal last decision metadata, err: %w", err)
692		}
693		if md.ViewId >= vd.NextView {
694			return 0, fmt.Errorf("last decision view %d is greater or equal to requested next view %d", md.ViewId, vd.NextView)
695		}
696		numSigs := len(vd.LastDecisionSignatures)
697		if numSigs < quorum {
698			return 0, fmt.Errorf("there are only %d last decision signatures", numSigs)
699		}

700		nodesMap := make(map[uint64]struct{}, n)
701		validSig := 0
702		for _, sig := range vd.LastDecisionSignatures {
703			if _, exist := nodesMap[sig.Signer]; exist {
704				continue // seen signature from this node already
705			}
706			nodesMap[sig.Signer] = struct{}{}
707			signature := types.Signature{
708				ID:    sig.Signer,
709				Value: sig.Value,
710				Msg:   sig.Msg,
711			}
712			proposal := types.Proposal{
713				Header:               vd.LastDecision.Header,
714				Payload:              vd.LastDecision.Payload,
715				Metadata:             vd.LastDecision.Metadata,
716				VerificationSequence: int64(vd.LastDecision.VerificationSequence),
717			}
718			if _, err = verifier.VerifyConsenterSig(signature, proposal); err != nil {
719				return 0, fmt.Errorf("last decision signature is invalid, error: %w", err)
720			}
721			validSig++
722		}
723		if validSig < quorum {
724			return 0, fmt.Errorf("there are only %d valid last decision signatures", validSig)
725		}
726		return md.LatestSequence, nil
727	}
