931	func (v *ViewChanger) validateNewViewMsg(msg *protos.NewView) (valid bool, sync bool, deliver bool) {
932		signed := msg.GetSignedViewData()
933		nodesMap := make(map[uint64]struct{}, v.N)
934		validViewDataMsgs := 0
935		mySequence, myLastDecision := v.extractCurrentSequence()
936		for _, svd := range signed {
937			if _, exist := nodesMap[svd.Signer]; exist {
938				continue // seen data from this node already
939			}
940			nodesMap[svd.Signer] = struct{}{}
941	
942			vd := &protos.ViewData{}
943			if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
944				v.Logger.Errorf("Node %d was unable to unmarshal viewData from the newView message, error: %v", v.SelfID, err)
945				return false, false, false
946			}
947	
948			if vd.NextView != v.currView {
949				v.Logger.Warnf("Node %d is processing newView message, but nextView of %s is %d, while the currView is %d", v.SelfID, signedViewDataToString(svd), vd.NextView, v.currView)

1050			}
1051	
1052			proposal := types.Proposal{
1053				Header:               vd.LastDecision.Header,
1054				Metadata:             vd.LastDecision.Metadata,
1055				Payload:              vd.LastDecision.Payload,
1056				VerificationSequence: int64(vd.LastDecision.VerificationSequence),
1057			}
1058			signatures := make([]types.Signature, 0)
1059			for _, sig := range vd.LastDecisionSignatures {
1060				signature := types.Signature{
1061					ID:    sig.Signer,
1062					Value: sig.Value,
1063					Msg:   sig.Msg,
1064				}
1065				signatures = append(signatures, signature)
1066			}
1067			v.deliverDecision(proposal, signatures)
1068	
1069			select { // if there was a delivery with a reconfig we need to stop here before verify signature
1070			case <-v.stopChan:
1071				return false, false, false
1072			default:
1073			}
1074	
1075			if err = v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
1076				v.Logger.Warnf("Node %d is processing newView message, but signature of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1077				return false, false, false
1078			}
1079	
1080			if err = ValidateInFlight(vd.InFlightProposal, lastDecisionMD.LatestSequence); err != nil {
1081				v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1082				return false, false, false
1083			}
1084	
1085			return true, false, true
1086		}
1087	
1088		if validViewDataMsgs < v.quorum {
1089			v.Logger.Warnf("Node %d is processing newView message, but there was only %d valid view data messages while the quorum is %d", v.SelfID, validViewDataMsgs, v.quorum)
1090			return false, false, false
1091		}
1092	
1093		v.Logger.Debugf("Node %d found a quorum of valid view data messages within the new view message", v.SelfID)
1094		return true, false, false
1095	}
