1110	func (v *ViewChanger) processNewViewMsg(msg *protos.NewView) {
1111		valid, calledSync, calledDeliver := v.validateNewViewMsg(msg)
1112		for calledDeliver {
1113			v.Logger.Debugf("Node %d is processing a newView message, and delivered a proposal", v.SelfID)
1114			valid, calledSync, calledDeliver = v.validateNewViewMsg(msg)
1115		}
1116		if !valid {
1117			v.Logger.Warnf("Node %d is processing a newView message, but the message is invalid", v.SelfID)
1118			return
1119		}
1120		if calledSync {
1121			v.Logger.Debugf("Node %d is processing a newView message, and requested a sync", v.SelfID)
1122			return
1123		}
1124	
1125		ok, noInFlight, inFlightProposal, err := CheckInFlight(v.extractViewDataMessages(msg), v.f, v.quorum, v.N, v.Verifier)
1126		if err != nil {
1127			v.Logger.Panicf("The check of the in flight proposal by node %d returned an error: %v", v.SelfID, err)
1128		}
1129		if !ok {
1130			v.Logger.Debugf("The check of the in flight proposal by node %d did not pass", v.SelfID)
1131			return
1132		}
1133	
1134		if !noInFlight && !v.commitInFlightProposal(inFlightProposal) {
1135			v.Logger.Warnf("Node %d was unable to commit the in flight proposal, not changing the view", v.SelfID)
1136			return
1137		}
1138	
1139		mySequence, _ := v.extractCurrentSequence()
1140	
1141		newViewToSave := &protos.SavedMessage{
1142			Content: &protos.SavedMessage_NewView{
1143				NewView: &protos.ViewMetadata{
1144					ViewId:         v.currView,
1145					LatestSequence: mySequence,
1146				},
1147			},
1148		}
1149		if err = v.State.Save(newViewToSave); err != nil {
1150			v.Logger.Panicf("Failed to save message to state, error: %v", err)
1151		}
1152	
1153		select { // if there was a delivery or sync with a reconfig when committing the in-flight proposal we should stop
1154		case <-v.stopChan:
1155			return
1156		default:
1157		}
1158	
1159		v.realView = v.currView
1160		v.MetricsViewChange.RealView.Set(float64(v.realView))
1161		v.nvs.clear()
1162		v.Controller.ViewChanged(v.currView, mySequence+1)
1163	
1164		v.RequestsTimer.RestartTimers()
1165		v.checkTimeout = false
1166		v.backOffFactor = 1 // reset
1167	}
