378	func (hm *HeartbeatMonitor) followerTick(now time.Time) {
379		if hm.timedOut || hm.lastHeartbeat.IsZero() {
380			hm.lastHeartbeat = now
381			return
382		}
383	
384		delta := now.Sub(hm.lastHeartbeat)
385		if delta >= hm.hbTimeout {
386			hm.logger.Warnf("Heartbeat timeout (%v) from %d expired; last heartbeat was observed %s ago",
387				hm.hbTimeout, hm.leaderID, delta)
388			hm.handler.OnHeartbeatTimeout(hm.view, hm.leaderID)
389			hm.timedOut = true
390			return
391		}
392	
393		hm.logger.Debugf("Last heartbeat from %d was %v ago", hm.leaderID, delta)
394	
395		if !hm.followerBehind {
396			return
397		}
398	
399		hm.behindCounter++
400		if hm.behindCounter >= hm.numOfTicksBehindBeforeSyncing {

400		if hm.behindCounter >= hm.numOfTicksBehindBeforeSyncing {
401			hm.logger.Warnf("Syncing since the follower with seq %d is behind the leader for the last %d ticks", hm.behindSeq, hm.numOfTicksBehindBeforeSyncing)
402			hm.handler.Sync()
403			hm.behindCounter = 0
404			return
405		}
406	}
